from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, Preformatted
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.colors import HexColor, white
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.enums import TA_LEFT
import shutil

root = Path(__file__).resolve().parent.parent
pdfmetrics.registerFont(TTFont('Arial', 'C:/Windows/Fonts/arial.ttf'))
pdfmetrics.registerFont(TTFont('ArialBold', 'C:/Windows/Fonts/arialbd.ttf'))
pdfmetrics.registerFontFamily('Arial', normal='Arial', bold='ArialBold', italic='Arial', boldItalic='ArialBold')
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='BodyVN', fontName='Arial', fontSize=10.5, leading=16, spaceAfter=10, textColor=HexColor('#172c44')))
styles.add(ParagraphStyle(name='TitleVN', fontName='ArialBold', fontSize=25, leading=32, spaceAfter=16, textColor=HexColor('#034ea1')))
styles.add(ParagraphStyle(name='HeadVN', fontName='ArialBold', fontSize=14, leading=20, spaceBefore=12, spaceAfter=8, textColor=HexColor('#034ea1')))
styles.add(ParagraphStyle(name='SmallVN', fontName='Arial', fontSize=9, leading=13, spaceAfter=7, textColor=HexColor('#52657b')))
styles.add(ParagraphStyle(name='CodeVN', fontName='Courier', fontSize=8, leading=12, spaceAfter=12, backColor=HexColor('#edf3fa'), borderPadding=10))
story=[]
def p(text, style='BodyVN'): story.append(Paragraph(text, styles[style]))
def h(text): p(text, 'HeadVN')
def code(text): story.append(Preformatted(text, styles['CodeVN']))
def page(label,title):
    if story: story.append(PageBreak())
    p('UET ARENA · VNU–UET · 23/10/2026', 'SmallVN'); p(title,'TitleVN'); p(label,'SmallVN')
def table(rows, widths):
    t=Table([[Paragraph(escape(c),styles['SmallVN']) for c in row] for row in rows],colWidths=widths,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#e2ecf9')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,-1),.5,HexColor('#d6dfe9'))]))
    story.append(t); story.append(Spacer(1,12))
page('Hướng dẫn mô hình website cloud + bộ chấm tại máy BTC','Thi online, chấm trên máy BTC')
p('Website: <link href="https://oan-tu-ti-ai-arena.vercel.app/competition" color="#034ea1">oan-tu-ti-ai-arena.vercel.app/competition</link>')
p('Không cần mua tên miền, mở cổng máy chấm hay dùng tunnel. Website nhận bài trên Vercel; máy BTC chủ động lấy công việc và gửi kết quả qua HTTPS.')
table([['Bên tham gia','Cần dùng gì?'],['Sinh viên','Trình duyệt; Python và editor để tự phát triển bot nếu muốn.'],['BTC điều hành','Trình duyệt và tài khoản được cấp quyền Ban tổ chức.'],['Người kỹ thuật','Vercel + Neon; máy chấm có Docker Desktop. Git và Node 22.16+ phục vụ thiết lập.']],[135,360])
h('Luồng hoạt động')
table([['Thành phần','Trách nhiệm'],['Sinh viên → Vercel','Đăng nhập, đổi mã đội, nộp bot.py, xem bảng đấu và replay.'],['Vercel → Neon','Lưu tài khoản, source, phiên bản luật, hàng đợi và kết quả.'],['Docker → Vercel','Xin việc, giữ lease/heartbeat, gửi kết quả bằng secret riêng.'],['Docker → sandbox','Mỗi bot chạy riêng trong CPython WASI/Wasmtime; không được cấp mạng, secret hoặc tệp của máy BTC.']],[135,360])
p('Vercel không chạy Python của bài thi. Worker không có mật khẩu database. Chỉ người kỹ thuật giữ quyền database và cấu hình triển khai.', 'SmallVN')
page('Cấu hình một lần · người kỹ thuật','Chuẩn bị website và máy chấm')
h('1. Website')
p('Kết nối repository với Vercel; dùng vercel.json đã có. Kết nối Neon và đặt DATABASE_URL trong môi trường Production. Build tạo schema arena_competition riêng, giữ dữ liệu Vercel hiện có.')
h('2. Tạo cấu hình worker trên máy BTC')
code('npm run judge:cloud:init')
p('Lệnh tạo .env.judge.local và .secrets/vercel-judge-token. Đặt đúng nội dung token làm biến server JUDGE_TOKEN trong Vercel Production, sau đó redeploy. Hai file local này không nằm trong Git hoặc gói upload Vercel.')
p('<b>Không</b> đưa token vào NEXT_PUBLIC_*, bài nộp hoặc nhóm sinh viên. Người quản lý có thể nhập token trong phần Environment Variables của Vercel; lệnh PowerShell nằm trong hướng dẫn Markdown đi kèm.')
h('3. Cấp quyền BTC')
p('BTC đăng ký tài khoản thật trên website. Chủ database xác nhận đúng tài khoản rồi cấp quyền:')
code('node --env-file=.env.vercel.local scripts/vercel-admin.mjs\n  your@email.com')
p('Lệnh trên trình bày trên hai dòng cho dễ đọc; khi chạy, nhập thành một dòng. Sau đó vào /competition → Ban tổ chức. Không cấp quyền dựa trên tên hiển thị hoặc email tự khai.')
h('4. Bật Docker')
code('docker compose -f compose.judge.yaml --env-file\n  .env.judge.local up -d --build')
p('Nhập lệnh thành một dòng. Docker Desktop phải đang chạy Linux containers. Worker giới hạn 2 CPU, 2 GiB RAM; nên bắt đầu với máy có RAM 8 GiB trở lên và SSD. Đây chưa phải cấu hình được chứng nhận cho 4.000 người.')
p('Mã nguồn: github.com/nguyenlean17/oan-tu-ti-ai-arena', 'SmallVN')
page('Thao tác thường ngày · BTC và sinh viên','Từ nộp bài đến công bố')
h('Ban tổ chức')
p('1. Vào Ban tổ chức → Tạo giải đấu mới. Chọn số bảng, suất đi tiếp, hạn nộp và giới hạn thời gian/bộ nhớ. Chốt luật trước khi nhận bài.')
p('2. Nhập danh sách đội và sinh viên; phát mã tham gia riêng cho đúng người. Mã được gắn với email và MSSV trong danh sách BTC.')
p('3. Mở nhận bài. Theo dõi bộ chấm và hàng đợi. Bài lỗi bị đánh dấu không hợp lệ; sinh viên có thể sửa và nộp lại trong hạn.')
p('4. Hết hạn, khóa danh sách sau khi kiểm tra hết bài chờ. Hệ thống lấy bài hợp lệ mới nhất trước hạn, chia bảng và chạy các cặp đổi bên.')
p('5. Kết thúc loại trực tiếp, kiểm tra replay và công bố. Xuất toàn bộ giải để lưu source đã khóa, config và diễn biến.')
h('Sinh viên')
p('Mở website → đăng ký/đăng nhập → nhập mã để vào đội → nộp bot.py → xem trạng thái kiểm tra bài → theo dõi lịch đấu, bảng điểm và replay.')
p('Có thể nhập bot.py từ commit GitHub đầy đủ trong repo công khai đã được BTC gắn cho đội. Git không thay thế tài khoản, mã đội hoặc sandbox. Không cần cài Docker để tham gia.')
h('Giới hạn và thời gian chờ')
p('Mỗi đội: một phiên bản mỗi 5 giây, tối đa hai bài chờ kiểm tra và 200 phiên bản trong giải. Python WASI không hỗ trợ pip, socket, subprocess hay extension native.')
p('Worker rảnh lấy việc theo khoảng tăng dần khoảng 5–15 giây. Trang đang mở cập nhật khoảng 15 giây; giải đã công bố ngừng polling. Thời gian trả kết quả còn phụ thuộc hàng đợi, CPU và bot; không cam kết tức thì.')
p('Trước ngày thi, thử bot hợp lệ, bot sai luật, chấm trận và replay bằng đúng image/runtime sẽ dùng trong giải.', 'SmallVN')
page('Sự cố, hạn mức và bảo toàn dữ liệu','Vận hành an toàn, tiết kiệm')
h('Mất mạng hoặc máy chấm tắt')
p('Website vẫn nhận bài; công việc nằm trong PostgreSQL. Khi worker trở lại, nó tiếp tục nhận việc. Lease 90 giây, heartbeat 20 giây; kết quả lease cũ bị từ chối. Gửi lại cùng kết quả không cộng điểm hai lần.')
p('Lỗi hạ tầng được thử hữu hạn. Nếu job thất bại, BTC xem hàng đợi, xử lý nguyên nhân rồi thử lại. Nếu runtime khác phiên bản giải đã khóa, hệ thống dừng chấm để tránh âm thầm đổi luật.')
h('Hết buổi: dừng worker')
code('docker compose -f compose.judge.yaml --env-file\n  .env.judge.local stop')
p('Nhập thành một dòng. Lần sau bật lại bằng up -d. Polling liên tục có thể giữ database luôn thức và tiêu hao hạn mức miễn phí; hãy dừng worker khi không tổ chức giải.')
h('Sao lưu và ranh giới dữ liệu')
p('Xuất giải từ admin panel để giữ source đã khóa, cấu hình và replay. Dùng backup/export PostgreSQL của tài khoản Neon để bảo vệ toàn bộ database; export giải không thay thế backup tài khoản.')
p('Dữ liệu trong volume Docker cũ vẫn được giữ tại máy và không tự nhập lên website công khai. Dữ liệu Vercel trước đây được giữ. File .env.vercel.local có quyền database: chỉ người kỹ thuật giữ, không gửi cho máy chấm khác.')
h('Giới hạn hiện tại')
p('Cấu hình pilot tuần tự hóa thao tác ghi bằng khóa giao dịch PostgreSQL; truy vấn đọc không chờ khóa ghi đó. Khi đo thấy nghẽn, cần tách khóa theo giải/job và cache bảng điểm. Chưa cam kết chịu tải 4.000 sinh viên đồng thời hoặc chi phí luôn bằng 0.')
p('Chưa có SSO trường, xác minh email tự động hoặc khôi phục mật khẩu. BTC xác nhận danh sách, phát mã riêng; duy trì cập nhật OS/runtime và chỉ dùng máy chấm do BTC quản lý.')
p('Hướng dẫn lệnh đầy đủ và kiểm thử: deploy/VERCEL_JUDGE.md trong repository.', 'SmallVN')

out=root/'output/pdf/huong-dan-vercel-docker-uet.pdf';out.parent.mkdir(parents=True,exist_ok=True)
